// NormalizeSPOTenant rewrites a read-back SPOTenant object in place: enum properties (returned
// as integers) become their member name.
func NormalizeSPOTenant(obj map[string]any) {
	for prop, names := range sPOTenantEnumNames {
		if v, ok := obj[prop]; ok {
			if f, ok := v.(float64); ok {
				if nm, ok := names[int(f)]; ok {
					obj[prop] = nm
				}
			}
		}
	}
}

