// NormalizeSPOSite rewrites a read-back SPOSite object in place: enum properties (returned
// as integers) become their member name.
func NormalizeSPOSite(obj map[string]any) {
	for prop, names := range sPOSiteEnumNames {
		if v, ok := obj[prop]; ok {
			if f, ok := v.(float64); ok {
				if nm, ok := names[int(f)]; ok {
					obj[prop] = nm
				}
			}
		}
	}
}

// GetSPOSiteParams targets a site collection by URL.
type GetSPOSiteParams struct {
	Identity string `spo:"Identity"` // the site URL
}

func siteChain(url string) []spoapi.PathStep {
	return []spoapi.PathStep{{
		Method: "GetSitePropertiesByUrl",
		Params: []spoapi.Param{{Type: spoapi.TypeString, Value: url}, {Type: spoapi.TypeBoolean, Value: true}},
	}}
}

// GetSPOSite reads a site collection's admin settings (Get-SPOSite -Identity <url>).
func (s *Service) GetSPOSite(ctx context.Context, p GetSPOSiteParams) (*spoapi.Result, error) {
	res, err := s.C.Invoke(ctx, spoapi.Op{CmdletName: "Get-SPOSite", TypeID: spoapi.TenantTypeID, Chain: siteChain(p.Identity), Query: true})
	if err != nil {
		return nil, err
	}
	for _, obj := range res.Value {
		NormalizeSPOSite(obj)
		if _, ok := obj["Identity"]; !ok {
			obj["Identity"] = p.Identity
		}
	}
	return res, nil
}

// SetSPOSite applies the bound knobs to an existing site (Set-SPOSite -Identity <url>).
func (s *Service) SetSPOSite(ctx context.Context, p SetSPOSiteParams) (*spoapi.Result, error) {
	res, err := s.C.Invoke(ctx, spoapi.Op{
		CmdletName: "Set-SPOSite", TypeID: spoapi.TenantTypeID,
		Chain: siteChain(p.Identity), Set: setPropsSPOSite(p), Update: true, Query: true,
	})
	if err != nil {
		return nil, err
	}
	for _, obj := range res.Value {
		NormalizeSPOSite(obj)
		if _, ok := obj["Identity"]; !ok {
			obj["Identity"] = p.Identity
		}
	}
	return res, nil
}
